// RequireFields returns ErrInvalidArgument naming the first of fields (m's
// top-level field names) m leaves unset: a message without a value, a
// repeated or map field without elements. The REQUIRED document columns are
// NOT NULL, so a write without one would otherwise fail in the database.
func RequireFields(m proto.Message, fields ...string) error {
	r := m.ProtoReflect()
	for _, f := range fields {
		fd := r.Descriptor().Fields().ByName(protoreflect.Name(f))
		if fd == nil {
			continue
		}
		set := r.Has(fd)
		if fd.IsList() {
			set = r.Get(fd).List().Len() > 0
		} else if fd.IsMap() {
			set = r.Get(fd).Map().Len() > 0
		}
		if !set {
			return fmt.Errorf("%w: %s is required", ErrInvalidArgument, f)
		}
	}
	return nil
}

// AllWild reports whether every id of a split parent name is AIP-159's "-":
// a read across every parent. A parent with some ids named and some "-"
// ("venues/v1/events/-") reads under the named ones only.
func AllWild(ids []string) bool {
	for _, id := range ids {
		if id != "-" {
			return false
		}
	}
	return true
}

// Joined holds what join tables keep for a page of rows: the names each
// row's field lists, by field and then by the row's key.
type Joined map[string]map[string][]string

// Join is a join table keeping a repeated reference field: one row per
// element, in the order the field lists them (rows are keyed by ULIDs minted
// in that order).
